const todos = ['Belajar Git', 'Beli kopi'];
function tambahTodo(teks) { todos.push(teks); }
function hapusTodo(i) { todos.splice(i, 1); }
function tandaiSelesai(i) { todos[i] = '[x] ' + todos[i]; }
function cariTodo(kata) { return todos.filter((t) => t.includes(kata)); }
function urutkanTodo() { return [...todos].sort(); }
